import 'package:flutter/material.dart';
import '../services/gemini_service.dart';
class AISettingsScreen extends StatefulWidget{const AISettingsScreen({super.key});@override State<AISettingsScreen> createState()=>_AISettingsScreenState();}
class _AISettingsScreenState extends State<AISettingsScreen>{final key=TextEditingController();bool saved=false;@override void dispose(){key.dispose();super.dispose();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Online AI Setup')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Connect Gemini Free API',style:TextStyle(fontSize:22,fontWeight:FontWeight.w800)),const SizedBox(height:8),const Text('Enter your Gemini API key to enable real online Mentor and live Current Affairs. The key is stored on this device. For a public production app, use a secure backend instead of shipping a shared key inside the APK.'),const SizedBox(height:20),TextField(controller:key,obscureText:true,decoration:const InputDecoration(labelText:'OpenAI API key',hintText:'Paste key here',border:OutlineInputBorder())),const SizedBox(height:12),FilledButton.icon(onPressed:()async{if(key.text.trim().isEmpty)return;await GeminiService.saveApiKey(key.text);if(mounted)setState(()=>saved=true);},icon:const Icon(Icons.key_rounded),label:const Text('Save & enable Gemini AI')),if(saved)const Padding(padding:EdgeInsets.only(top:12),child:Text('Online AI enabled.'))]));}
